-- import_directory.sql  (generated by DB/build_directory_import.mjs)
-- Seeds the Directory with first-party Shetland businesses as UNCLAIMED listings.
-- Idempotent on slug: re-running updates name/description/category, never clobbers
-- a listing once it has been claimed (owner_id set).
BEGIN;

INSERT INTO public.local_businesses (name, description, category, slug, address, source, is_claimed, is_verified, is_active, owner_id, place_id, lat, lng)
VALUES ('Aa'' Fired Up', 'Aa'' Fired Up offers a relaxed and creative craft experience suitable for all ages. Visitors can enjoy pottery painting, make-your-own teddy bears, clay hand and foot impressions, and other personalised keepsakes. The studio also sells handmade gifts and provides refreshments such as tea, coffee and cakes. Craft kits and party packs are available for home use or special events.', 'food_drink', 'aa-fired-up', 'Shetland', 'csv', false, false, true, NULL, NULL, NULL, NULL)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = COALESCE(EXCLUDED.description, public.local_businesses.description), category = EXCLUDED.category, place_id = COALESCE(public.local_businesses.place_id, EXCLUDED.place_id), lat = COALESCE(public.local_businesses.lat, EXCLUDED.lat), lng = COALESCE(public.local_businesses.lng, EXCLUDED.lng) WHERE public.local_businesses.owner_id IS NULL;

INSERT INTO public.local_businesses (name, description, category, slug, address, source, is_claimed, is_verified, is_active, owner_id, place_id, lat, lng)
VALUES ('Anderson & Co', 'Anderson & Co is a long-established family business specialising in Shetland knitwear, crafts, and children’s clothing. Founded in 1873, the shop produces and sells traditional garments made from genuine Shetland wool, valued for its warmth and softness. Alongside knitwear, they offer accessories, knitting supplies, patterns, wool and craft materials.', 'retail', 'anderson-and-co', 'Shetland', 'csv', false, false, true, NULL, NULL, NULL, NULL)
