ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = COALESCE(EXCLUDED.description, public.local_businesses.description), category = EXCLUDED.category, place_id = COALESCE(public.local_businesses.place_id, EXCLUDED.place_id), lat = COALESCE(public.local_businesses.lat, EXCLUDED.lat), lng = COALESCE(public.local_businesses.lng, EXCLUDED.lng) WHERE public.local_businesses.owner_id IS NULL;

